import{_ as a,o as n,c as e,a5 as t}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"75. Logging Systems","description":"The Little Book of C — 75. Logging Systems","frontmatter":{"title":"75. Logging Systems","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Debugging Testing Profiling"],"description":"The Little Book of C — 75. Logging Systems","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":75,"sidebarWeight":75,"lang":"en-US","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/075-Logging Systems","alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/075-Logging Systems"},"headers":[],"relativePath":"posts/c教程/en-US/08-Debugging Testing Profiling/075-Logging Systems.md","filePath":"posts/c教程/en-US/08-Debugging Testing Profiling/075-Logging Systems.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/08-Debugging Testing Profiling/075-Logging Systems.md"};function p(o,s,l,c,g,r){return n(),e("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/08-调试测试与 profiling/075-Logging Systems)</p><p>As your programs grow, printf debugging quickly becomes messy. You need a way to see inside your program, what it’s doing, what went wrong, and why, without flooding your terminal with random messages.</p><p>That’s where logging systems come in. A good log system helps you trace execution, record errors, and understand how your program behaves over time.</p><h4 id="step-1-what-is-logging" tabindex="-1">Step 1. What Is Logging? <a class="header-anchor" href="#step-1-what-is-logging" aria-label="Permalink to &quot;Step 1. What Is Logging?&quot;">​</a></h4><p>Logging is like keeping a diary for your program. Instead of printing everything to the screen, you log structured messages with levels (INFO, WARN, ERROR) and timestamps.</p><p>It’s essential for:</p><ul><li>Debugging complex flows.</li><li>Auditing events and errors.</li><li>Monitoring long-running services.</li><li>Diagnosing crashes and performance issues.</li></ul><h4 id="step-2-the-simplest-logger-printf-with-context" tabindex="-1">Step 2. The Simplest Logger, printf with Context <a class="header-anchor" href="#step-2-the-simplest-logger-printf-with-context" aria-label="Permalink to &quot;Step 2. The Simplest Logger, printf with Context&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;[INFO] Starting program\\n&quot;);</span></span>
<span class="line"><span>    printf(&quot;[WARN] Low memory\\n&quot;);</span></span>
<span class="line"><span>    printf(&quot;[ERROR] Failed to open file\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This works, but there’s no timestamp, file name, or severity control.</p><h4 id="step-3-adding-log-levels-and-macros" tabindex="-1">Step 3. Adding Log Levels and Macros <a class="header-anchor" href="#step-3-adding-log-levels-and-macros" aria-label="Permalink to &quot;Step 3. Adding Log Levels and Macros&quot;">​</a></h4><p>We can make this structured and reusable using macros.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#define LOG(level, msg, ...) do { \\</span></span>
<span class="line"><span>    time_t t = time(NULL); \\</span></span>
<span class="line"><span>    struct tm *tm_info = localtime(&amp;t); \\</span></span>
<span class="line"><span>    char buf[20]; \\</span></span>
<span class="line"><span>    strftime(buf, 20, &quot;%Y-%m-%d %H:%M:%S&quot;, tm_info); \\</span></span>
<span class="line"><span>    fprintf(stderr, &quot;[%s] [%s] &quot; msg &quot;\\n&quot;, buf, level, ##__VA_ARGS__); \\</span></span>
<span class="line"><span>} while (0)</span></span>
<span class="line"><span>#define LOG_INFO(msg, ...)  LOG(&quot;INFO&quot;, msg, ##__VA_ARGS__)</span></span>
<span class="line"><span>#define LOG_WARN(msg, ...)  LOG(&quot;WARN&quot;, msg, ##__VA_ARGS__)</span></span>
<span class="line"><span>#define LOG_ERROR(msg, ...) LOG(&quot;ERROR&quot;, msg, ##__VA_ARGS__)</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    LOG_INFO(&quot;Program started&quot;);</span></span>
<span class="line"><span>    LOG_WARN(&quot;Memory usage at %d%%&quot;, 80);</span></span>
<span class="line"><span>    LOG_ERROR(&quot;File %s not found&quot;, &quot;data.txt&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[2025-10-16 23:41:09] [INFO] Program started</span></span>
<span class="line"><span>[2025-10-16 23:41:09] [WARN] Memory usage at 80%</span></span>
<span class="line"><span>[2025-10-16 23:41:09] [ERROR] File data.txt not found</span></span></code></pre></div><p>Now your logs have consistent structure and useful context.</p><h4 id="step-4-controlling-log-verbosity" tabindex="-1">Step 4. Controlling Log Verbosity <a class="header-anchor" href="#step-4-controlling-log-verbosity" aria-label="Permalink to &quot;Step 4. Controlling Log Verbosity&quot;">​</a></h4><p>Add a global log level:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>enum { LOG_LEVEL_INFO, LOG_LEVEL_WARN, LOG_LEVEL_ERROR };</span></span>
<span class="line"><span>int CURRENT_LOG_LEVEL = LOG_LEVEL_INFO;</span></span>
<span class="line"><span>#define SHOULD_LOG(level) ((level) &gt;= CURRENT_LOG_LEVEL)</span></span>
<span class="line"><span>#define LOGX(level, tag, msg, ...) do { \\</span></span>
<span class="line"><span>    if (SHOULD_LOG(level)) { \\</span></span>
<span class="line"><span>        time_t t = time(NULL); \\</span></span>
<span class="line"><span>        struct tm *tm_info = localtime(&amp;t); \\</span></span>
<span class="line"><span>        char buf[20]; \\</span></span>
<span class="line"><span>        strftime(buf, 20, &quot;%H:%M:%S&quot;, tm_info); \\</span></span>
<span class="line"><span>        fprintf(stderr, &quot;[%s] [%s] &quot; msg &quot;\\n&quot;, buf, tag, ##__VA_ARGS__); \\</span></span>
<span class="line"><span>    } \\</span></span>
<span class="line"><span>} while (0)</span></span></code></pre></div><p>Now:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LOGX(LOG_LEVEL_INFO, &quot;INFO&quot;, &quot;Running&quot;);</span></span>
<span class="line"><span>LOGX(LOG_LEVEL_WARN, &quot;WARN&quot;, &quot;Low disk space&quot;);</span></span>
<span class="line"><span>LOGX(LOG_LEVEL_ERROR, &quot;ERROR&quot;, &quot;Crash at line %d&quot;, __LINE__);</span></span></code></pre></div><p>Change verbosity dynamically:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CURRENT_LOG_LEVEL = LOG_LEVEL_WARN;</span></span></code></pre></div><p>Now INFO messages are skipped.</p><h4 id="step-5-logging-to-a-file" tabindex="-1">Step 5. Logging to a File <a class="header-anchor" href="#step-5-logging-to-a-file" aria-label="Permalink to &quot;Step 5. Logging to a File&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>void log_to_file(const char *filename, const char *msg) {</span></span>
<span class="line"><span>    FILE *f = fopen(filename, &quot;a&quot;);</span></span>
<span class="line"><span>    if (!f) return;</span></span>
<span class="line"><span>    time_t t = time(NULL);</span></span>
<span class="line"><span>    fprintf(f, &quot;%s: %s\\n&quot;, ctime(&amp;t), msg);</span></span>
<span class="line"><span>    fclose(f);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    log_to_file(&quot;log.txt&quot;, &quot;Program started&quot;);</span></span>
<span class="line"><span>    log_to_file(&quot;log.txt&quot;, &quot;Action complete&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The log file will contain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thu Oct 16 23:41:09 2025: Program started</span></span>
<span class="line"><span>Thu Oct 16 23:41:10 2025: Action complete</span></span></code></pre></div><h4 id="step-6-including-file-and-line-information" tabindex="-1">Step 6. Including File and Line Information <a class="header-anchor" href="#step-6-including-file-and-line-information" aria-label="Permalink to &quot;Step 6. Including File and Line Information&quot;">​</a></h4><p>You can include source info automatically using<code>__FILE__</code> and<code>__LINE__</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define LOG_DEBUG(msg, ...) \\</span></span>
<span class="line"><span>    fprintf(stderr, &quot;[DEBUG] %s:%d &quot; msg &quot;\\n&quot;, __FILE__, __LINE__, ##__VA_ARGS__)</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LOG_DEBUG(&quot;x = %d&quot;, x);</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[DEBUG] main.c:42 x = 10</span></span></code></pre></div><h4 id="step-7-rotating-or-limiting-logs" tabindex="-1">Step 7. Rotating or Limiting Logs <a class="header-anchor" href="#step-7-rotating-or-limiting-logs" aria-label="Permalink to &quot;Step 7. Rotating or Limiting Logs&quot;">​</a></h4><p>For long-running programs, you don’t want logs to grow forever. You can:</p><ul><li>Truncate or rename old files.</li><li>Only keep N entries.</li><li>Write daily logs (<code>log_2025-10-16.txt</code>).</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>char filename[64];</span></span>
<span class="line"><span>time_t now = time(NULL);</span></span>
<span class="line"><span>strftime(filename, sizeof(filename), &quot;log_%Y-%m-%d.txt&quot;, localtime(&amp;now));</span></span>
<span class="line"><span>log_to_file(filename, &quot;Daily entry&quot;);</span></span></code></pre></div><h4 id="step-8-adding-colors-optional" tabindex="-1">Step 8. Adding Colors (Optional) <a class="header-anchor" href="#step-8-adding-colors-optional" aria-label="Permalink to &quot;Step 8. Adding Colors (Optional)&quot;">​</a></h4><p>Make console logs easier to read with ANSI color codes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define RED   &quot;\\x1b[31m&quot;</span></span>
<span class="line"><span>#define YEL   &quot;\\x1b[33m&quot;</span></span>
<span class="line"><span>#define GRN   &quot;\\x1b[32m&quot;</span></span>
<span class="line"><span>#define RST   &quot;\\x1b[0m&quot;</span></span>
<span class="line"><span>#define LOGC(level, color, msg, ...) \\</span></span>
<span class="line"><span>    fprintf(stderr, color &quot;[%s] &quot; msg RST &quot;\\n&quot;, level, ##__VA_ARGS__)</span></span></code></pre></div><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LOGC(&quot;INFO&quot;, GRN, &quot;Server started&quot;);</span></span>
<span class="line"><span>LOGC(&quot;WARN&quot;, YEL, &quot;High CPU usage&quot;);</span></span>
<span class="line"><span>LOGC(&quot;ERROR&quot;, RED, &quot;Out of memory&quot;);</span></span></code></pre></div><h4 id="step-9-combining-logging-and-assertions" tabindex="-1">Step 9. Combining Logging and Assertions <a class="header-anchor" href="#step-9-combining-logging-and-assertions" aria-label="Permalink to &quot;Step 9. Combining Logging and Assertions&quot;">​</a></h4><p>You can combine assertions with logs for extra safety:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;assert.h&gt;</span></span>
<span class="line"><span>#define SAFE_LOG(cond, msg, ...) \\</span></span>
<span class="line"><span>    if (!(cond)) { \\</span></span>
<span class="line"><span>        LOG_ERROR(msg, ##__VA_ARGS__); \\</span></span>
<span class="line"><span>        assert(cond); \\</span></span>
<span class="line"><span>    }</span></span></code></pre></div><p>If something fails, it both logs and triggers an assertion.</p><h4 id="step-10-tiny-code-minimal-logger" tabindex="-1">Step 10. Tiny Code: Minimal Logger <a class="header-anchor" href="#step-10-tiny-code-minimal-logger" aria-label="Permalink to &quot;Step 10. Tiny Code: Minimal Logger&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#define LOG(fmt, ...) do { \\</span></span>
<span class="line"><span>    time_t now = time(NULL); \\</span></span>
<span class="line"><span>    char buf[20]; \\</span></span>
<span class="line"><span>    strftime(buf, sizeof(buf), &quot;%H:%M:%S&quot;, localtime(&amp;now)); \\</span></span>
<span class="line"><span>    fprintf(stderr, &quot;[%s] &quot; fmt &quot;\\n&quot;, buf, ##__VA_ARGS__); \\</span></span>
<span class="line"><span>} while (0)</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    LOG(&quot;Starting program&quot;);</span></span>
<span class="line"><span>    LOG(&quot;Loading config&quot;);</span></span>
<span class="line"><span>    LOG(&quot;Finished setup&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[23:42:00] Starting program</span></span>
<span class="line"><span>[23:42:01] Loading config</span></span>
<span class="line"><span>[23:42:02] Finished setup</span></span></code></pre></div><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>Logging makes invisible processes visible. It helps you:</p><ul><li>Trace execution flow.</li><li>Debug production code.</li><li>Audit errors and warnings.</li><li>Understand system performance over time.</li></ul><p>In real systems, servers, compilers, databases, logs are your lifeline when things go wrong.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Add<code>LOG_INFO</code>,<code>LOG_WARN</code>, and<code>LOG_ERROR</code> macros to one of your C projects.</li><li>Write logs to both<code>stderr</code> and a file.</li><li>Add timestamps and line numbers automatically.</li><li>Add colors for each level.</li><li>Implement a rotating file log system that keeps only today’s file active.</li></ol><p>Next, you’ll learn about profiling with gprof, how to measure where your program spends its time, and how to make it faster.</p>`,60)])])}const h=a(i,[["render",p]]);export{u as __pageData,h as default};
